import { execFileSync } from 'node:child_process';
import { readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { exportSpec } from './openapi-export';

// ---- the contract generated by the build (SI-03.29) ----

const PROJECT_ROOT = join(__dirname, '..');
const VERSIONED_CONTRACT = join(PROJECT_ROOT, 'openapi.json');
const ERROR_ENVELOPE = 'ApiErrorEnvelope';
const ref = (schema: string) => `#/components/schemas/${schema}`;

interface SchemaObject {
  type?: string;
  format?: string;
  $ref?: string;
  properties?: Record<string, SchemaObject>;
  required?: string[];
  items?: SchemaObject;
  oneOf?: SchemaObject[];
  nullable?: boolean;
  minLength?: number;
  maxLength?: number;
  minimum?: number;
  maximum?: number;
  uniqueItems?: boolean;
}

interface OperationObject {
  operationId: string;
  summary?: string;
  security?: Record<string, unknown>[];
  parameters?: {
    name: string;
    in: string;
    required?: boolean;
    schema?: SchemaObject;
  }[];
  requestBody?: {
    required?: boolean;
    content: Record<string, { schema: SchemaObject }>;
  };
  responses: Record<
    string,
    { description: string; content?: Record<string, { schema: SchemaObject }> }
  >;
}

interface OpenApiDocument {
  paths: Record<string, Record<string, OperationObject>>;
  components: { schemas: Record<string, SchemaObject> };
}

/**
 * The steps of `npm run openapi:export` (`nest build && node dist/openapi-export.js`), writing to
 * `outputPath` instead of the versioned contract. Only the build applies the CLI plugin of
 * @nestjs/swagger (openapi-docs-nestjs/TD-01), which documents the request DTOs from their
 * class-validator decorators; an export compiled by ts-node or ts-jest leaves them empty.
 */
function exportFromBuild(outputPath: string): void {
  execFileSync(join(PROJECT_ROOT, 'node_modules', '.bin', 'nest'), ['build'], {
    cwd: PROJECT_ROOT,
    stdio: 'pipe',
    timeout: 120_000,
  });
  execFileSync(
    process.execPath,
    [
      '-e',
      `require('./dist/openapi-export').exportSpec(${JSON.stringify(outputPath)}).then(() => process.exit(0))`,
    ],
    { cwd: PROJECT_ROOT, stdio: 'pipe', timeout: 60_000 },
  );
}

