describe('openapi.json generated by the build (integration)', () => {
  let outputPath: string;
  let generated: string;
  let document: OpenApiDocument;

  beforeAll(() => {
    outputPath = join(
      tmpdir(),
      `openapi-build-${process.pid}-${Date.now()}.json`,
    );
    exportFromBuild(outputPath);
    generated = readFileSync(outputPath, 'utf-8');
    document = JSON.parse(generated) as OpenApiDocument;
  }, 180_000);

  afterAll(() => {
    rmSync(outputPath, { force: true });
  });

  function schema(name: string): SchemaObject {
    const found = document.components.schemas[name];
    expect(found).toBeDefined();
    return found;
  }

  function jsonSchemaOf(body: {
    content?: Record<string, { schema: SchemaObject }>;
  }): SchemaObject | undefined {
    return body.content?.['application/json']?.schema;
  }

  /** Every `$ref` of the document, wherever it is. */
  function allRefs(value: unknown, found = new Set<string>()): Set<string> {
    if (Array.isArray(value)) {
      value.forEach((item) => allRefs(item, found));
    } else if (value && typeof value === 'object') {
      for (const [key, nested] of Object.entries(value)) {
        if (key === '$ref' && typeof nested === 'string') {
          found.add(nested);
        } else {
          allRefs(nested, found);
        }
      }
    }
    return found;
  }

  it('is byte for byte the versioned nestjs-project/openapi.json', () => {
    expect(readFileSync(VERSIONED_CONTRACT, 'utf-8')).toBe(generated);
  });

  describe('video routes', () => {
    it('documents exactly the operations of the phase under /videos', () => {
      const documented = Object.entries(document.paths)
        .filter(([path]) => path.startsWith('/videos'))
        .flatMap(([path, methods]) =>
          Object.keys(methods).map((method) => `${method} ${path}`),
        )
        .sort();

      expect(documented).toEqual(
        VIDEO_OPERATIONS.map((op) => `${op.method} ${op.path}`).sort(),
      );
    });

    it.each(VIDEO_OPERATIONS)(
      '$method $path: bearer, path parameters and one schema per documented status',
      ({ method, path, operationId, request, responses }) => {
        const operation = document.paths[path][method];

        expect(operation.operationId).toBe(operationId);
        expect(operation.summary?.length).toBeGreaterThan(0);
        expect(operation.security).toEqual([{ 'access-token': [] }]);
        const pathParameters = [...path.matchAll(/\{(\w+)\}/g)].map(
          ([, name]) => name,
        );
        expect(
          (operation.parameters ?? [])
            .filter((parameter) => parameter.in === 'path')
            .map(({ name, required }) => ({ name, required })),
        ).toEqual(pathParameters.map((name) => ({ name, required: true })));
        if (request) {
          expect(operation.requestBody?.required).toBe(true);
          expect(jsonSchemaOf(operation.requestBody!)).toEqual({
            $ref: ref(request),
          });
        } else {
          expect(operation.requestBody).toBeUndefined();
        }
        expect(Object.keys(operation.responses).sort()).toEqual(
          Object.keys(responses).sort(),
        );
        for (const [status, body] of Object.entries(responses)) {
          const response = operation.responses[status];
          expect(response.description.length).toBeGreaterThan(0);
          if (body === null) {
            expect(response.content).toBeUndefined();
          } else {
            expect(jsonSchemaOf(response)).toEqual({ $ref: ref(body) });
          }
        }
      },
    );

    it.each(Object.entries(VIDEO_RESPONSE_FIELDS))(
      'response %s has exactly its contract fields, all required',
      (name, fields) => {
        const response = schema(name);

        expect(Object.keys(response.properties ?? {}).sort()).toEqual(
          [...fields].sort(),
        );
        expect([...(response.required ?? [])].sort()).toEqual(
          [...fields].sort(),
        );
      },
    );
  });

  describe('request DTOs of the upload', () => {
    it('UploadDeclarationDto: fileName, sizeBytes and contentType, all required, with their limits', () => {
      const declaration = schema('UploadDeclarationDto');

      expect(declaration.type).toBe('object');
      expect(declaration.properties).toMatchObject({
        fileName: { type: 'string', minLength: 1, maxLength: 255 },
        sizeBytes: {
          type: 'number',
          minimum: 1,
          maximum: Number.MAX_SAFE_INTEGER,
        },
        contentType: { type: 'string', maxLength: 100 },
      });
      expect(Object.keys(declaration.properties ?? {}).sort()).toEqual([
        'contentType',
        'fileName',
        'sizeBytes',
      ]);
      expect(declaration.required).toEqual([
        'fileName',
        'sizeBytes',
        'contentType',
      ]);
    });

    it('PartUrlsRequestDto: optional parts and completedParts, arrays of PartToSignDto and CompletedPartDto', () => {
      const request = schema('PartUrlsRequestDto');

      expect(Object.keys(request.properties ?? {}).sort()).toEqual([
        'completedParts',
        'parts',
      ]);
      expect(request.properties).toMatchObject({
        parts: {
          type: 'array',
          items: { $ref: ref('PartToSignDto') },
        },
        completedParts: {
          type: 'array',
          items: { $ref: ref('CompletedPartDto') },
        },
      });
      // At least one non-empty array is a rule of the validation, not of the schema.
      expect(request.required).toBeUndefined();
    });

    it('PartToSignDto and CompletedPartDto: the fields of a part to sign and of a sent part, all required', () => {
      const toSign = schema('PartToSignDto');
      const completed = schema('CompletedPartDto');

      expect(toSign.properties).toMatchObject({
        partNumber: { type: 'number', minimum: 1 },
        checksumSha256: { type: 'string' },
      });
      expect(toSign.required).toEqual(['partNumber', 'checksumSha256']);
      expect(completed.properties).toMatchObject({
        partNumber: { type: 'number', minimum: 1 },
        etag: { type: 'string', minLength: 1, maxLength: 255 },
      });
      expect(completed.required).toEqual(['partNumber', 'etag']);
    });

    it('FileVerificationsRequestDto: required parts, unique items of RecalculatedPartChecksumDto', () => {
      const request = schema('FileVerificationsRequestDto');
      const recalculated = schema('RecalculatedPartChecksumDto');

      expect(Object.keys(request.properties ?? {})).toEqual(['parts']);
      expect(request.properties).toMatchObject({
        parts: {
          type: 'array',
          uniqueItems: true,
          items: { $ref: ref('RecalculatedPartChecksumDto') },
        },
      });
      expect(request.required).toEqual(['parts']);
      expect(recalculated.properties).toMatchObject({
        partNumber: { type: 'number', minimum: 1 },
        checksumSha256: { type: 'string' },
      });
      expect(recalculated.required).toEqual(['partNumber', 'checksumSha256']);
    });
  });

  describe('request DTOs of the auth', () => {
    it.each(AUTH_REQUEST_DTOS)(
      'POST $path takes $dto with its fields, all required',
      ({ path, dto, properties }) => {
        const operation = document.paths[path].post;
        const body = schema(dto);

        expect(operation.requestBody?.required).toBe(true);
        expect(jsonSchemaOf(operation.requestBody!)).toEqual({
          $ref: ref(dto),
        });
        expect(body.properties).toMatchObject(properties);
        expect(Object.keys(body.properties ?? {}).sort()).toEqual(
          Object.keys(properties).sort(),
        );
        expect([...(body.required ?? [])].sort()).toEqual(
          Object.keys(properties).sort(),
        );
      },
    );

    it('GET /auth/confirm-email takes the required token query parameter', () => {
      expect(document.paths['/auth/confirm-email'].get.parameters).toEqual([
        {
          name: 'token',
          in: 'query',
          required: true,
          schema: { type: 'string' },
        },
      ]);
    });
  });

  describe('error schemas', () => {
    it('ApiErrorEnvelope: statusCode, error and message required, nullable code', () => {
      const envelope = schema(ERROR_ENVELOPE);

      expect(envelope.properties).toMatchObject({
        statusCode: { type: 'number' },
        error: { type: 'string' },
        message: {
          oneOf: [
            { type: 'string' },
            { type: 'array', items: { type: 'string' } },
          ],
        },
        code: { type: 'string', nullable: true },
      });
      expect(envelope.required).toEqual(['statusCode', 'error', 'message']);
    });

    it('every 4xx and 5xx answer of every route uses ApiErrorEnvelope', () => {
      const errorAnswers = Object.entries(document.paths).flatMap(
        ([path, methods]) =>
          Object.entries(methods).flatMap(([method, operation]) =>
            Object.entries(operation.responses)
              .filter(([status]) => Number(status) >= 400)
              .map(([status, response]) => ({
                answer: `${method} ${path} ${status}`,
                schema: jsonSchemaOf(response),
              })),
          ),
      );

      expect(errorAnswers.length).toBeGreaterThan(0);
      for (const { answer, schema: body } of errorAnswers) {
        expect({ answer, body }).toEqual({
          answer,
          body: { $ref: ref(ERROR_ENVELOPE) },
        });
      }
    });

    it('every $ref of the document points to a schema of components.schemas', () => {
      const dangling = [...allRefs(document)].filter(
        (target) =>
          !target.startsWith('#/components/schemas/') ||
          !(
            target.slice('#/components/schemas/'.length) in
            document.components.schemas
          ),
      );

      expect(dangling).toEqual([]);
    });
  });
});

// ---- the export in process, compiled by ts-jest (without the CLI plugin) ----

describe('exportSpec (integration)', () => {
  let outputPath: string;
  let document: Record<string, unknown>;

  beforeAll(async () => {
    outputPath = join(tmpdir(), `openapi-test-${Date.now()}.json`);
    await exportSpec(outputPath);
    document = JSON.parse(readFileSync(outputPath, 'utf-8')) as Record<
      string,
      unknown
    >;
  }, 30_000);

  it('exports a valid OpenAPI 3.x document', () => {
    expect(document.openapi).toMatch(/^3\./);
  });

  it('sets info.title to "StreamTube API"', () => {
    const info = document.info as Record<string, unknown>;
    expect(info.title).toBe('StreamTube API');
  });

  it('sets info.version to "1.0"', () => {
    const info = document.info as Record<string, unknown>;
    expect(info.version).toBe('1.0');
  });

  it('includes access-token Bearer security scheme', () => {
    const components = document.components as Record<string, unknown>;
    const schemes = components.securitySchemes as Record<
      string,
      Record<string, unknown>
    >;
    expect(schemes['access-token']).toMatchObject({
      type: 'http',
      scheme: 'bearer',
      bearerFormat: 'JWT',
    });
  });

  it('includes non-empty components.schemas from DTO inference', () => {
    const components = document.components as Record<string, unknown>;
    const schemas = components.schemas as Record<string, unknown>;
    expect(Object.keys(schemas).length).toBeGreaterThan(0);
  });

  it('includes ApiErrorEnvelope schema with expected properties', () => {
    const components = document.components as Record<string, unknown>;
    const schemas = components.schemas as Record<
      string,
      Record<string, unknown>
    >;
    expect(schemas['ApiErrorEnvelope']).toBeDefined();
    const props = schemas['ApiErrorEnvelope'].properties as Record<
      string,
      unknown
    >;
    expect(props).toHaveProperty('statusCode');
    expect(props).toHaveProperty('error');
    expect(props).toHaveProperty('message');
    expect(props).toHaveProperty('code');
  });

  it('has at least one path with a 401 response referencing ApiErrorEnvelope', () => {
    const paths = document.paths as Record<
      string,
      Record<string, Record<string, unknown>>
    >;
    const apiErrorRef = '#/components/schemas/ApiErrorEnvelope';

    const hasRef = Object.values(paths).some((methods) =>
      Object.values(methods).some((operation) => {
        const responses = operation.responses as Record<
          string,
          Record<string, unknown>
        >;
        const r401 = responses?.['401'];
        if (!r401) return false;
        const content = r401.content as Record<string, Record<string, unknown>>;
        const jsonContent = content?.['application/json'];
        const schema = jsonContent?.schema as Record<string, unknown>;
        return schema?.['$ref'] === apiErrorRef;
      }),
    );

    expect(hasRef).toBe(true);
  });

  it('protected auth endpoints include access-token security requirement', () => {
    const paths = document.paths as Record<
      string,
      Record<string, Record<string, unknown>>
    >;
    const protectedPaths = [
      { path: '/auth/logout', method: 'post' },
      { path: '/auth/me', method: 'get' },
    ];

    for (const { path, method } of protectedPaths) {
      const operation = paths[path]?.[method];
      expect(operation).toBeDefined();
      const security = operation?.security as Array<Record<string, unknown>>;
      expect(security).toBeDefined();
      expect(security.some((req) => 'access-token' in req)).toBe(true);
    }
  });

  it('all auth endpoints have a non-empty summary', () => {
    const paths = document.paths as Record<
      string,
      Record<string, Record<string, unknown>>
    >;
    const authPaths = Object.entries(paths).filter(([p]) =>
      p.startsWith('/auth/'),
    );

    expect(authPaths.length).toBeGreaterThan(0);

    for (const [, methods] of authPaths) {
      for (const operation of Object.values(methods)) {
        expect(typeof operation.summary).toBe('string');
        expect((operation.summary as string).length).toBeGreaterThan(0);
      }
    }
  });
});
